"""Module topics bringing Survival Skills, Cooking, Foreign Languages,
and General Knowledge up to 20+ lessons per level (C1 through M1)."""

# Each of the subjects below is expanded with 18 genuinely distinct
# themes (beyond the 4 existing per-level themes already in the
# syllabus). Every theme is carried across all 7 levels with a
# level-appropriate prefix -- mirroring the "Foundations of / Building
# on / Core Theory / Applied Methods / Advanced / Capstone Study /
# Graduate Theory" progression already used elsewhere in the syllabus
# -- and a summary written at that level's depth, so titles are unique
# and content becomes more rigorous from C1 through M1.

LEVELS: list[str] = ["C1", "C2", "UG1", "UG2", "UG3", "UG4", "M1"]

_PREFIX: dict[str, str] = {
    "C1": "Foundations of {t}",
    "C2": "Building on {t}",
    "UG1": "Core Theory: {t}",
    "UG2": "Applied Methods: {t}",
    "UG3": "Advanced {t}",
    "UG4": "Capstone Study: {t}",
    "M1": "Graduate Theory: {t}",
}


def _expand(themes: list[tuple[str, list[str]]]) -> dict[str, list[tuple[str, str]]]:
    """Turn [(theme, [7 summaries C1..M1]), ...] into a per-level lesson list."""
    out: dict[str, list[tuple[str, str]]] = {lvl: [] for lvl in LEVELS}
    for theme, summaries in themes:
        assert len(summaries) == len(LEVELS), theme
        for lvl, summary in zip(LEVELS, summaries):
            out[lvl].append((_PREFIX[lvl].format(t=theme), summary))
    return out


